"""The Python planner must produce exactly the plans in tools/plan-fixtures (generated by core/videoplan)."""

import json
from pathlib import Path

import pytest
from jsonschema import Draft202012Validator

from bitacora_render.model import Trip, VideoPlan
from bitacora_render.planner import PlanParams, plan, plan_input_of

ROOT = Path(__file__).resolve().parents[2]
FIXTURES = ROOT / "tools" / "plan-fixtures"
SCHEMA = json.loads((ROOT / "docs" / "video-plan.schema.json").read_text(encoding="utf-8"))
CASES = sorted(p.name for p in FIXTURES.iterdir() if (p / "plan.json").exists())


@pytest.mark.parametrize("case", CASES)
def test_fixture_case_matches_kotlin_planner(case: str):
    d = FIXTURES / case
    trip = Trip.model_validate_json((d / "trip.json").read_text(encoding="utf-8"))
    params = PlanParams.from_dict(json.loads((d / "params.json").read_text(encoding="utf-8")))
    got = json.loads(plan(plan_input_of(trip), params).to_json())
    expected = json.loads((d / "plan.json").read_text(encoding="utf-8"))
    assert got == expected
    Draft202012Validator(SCHEMA).validate(got)
    assert VideoPlan.model_validate(got).total_duration_ms == expected["total_duration_ms"]


def test_cases_exist():
    assert len(CASES) >= 3, CASES
